{
  "name": "opencode-context-watch",
  "version": "1.0.6",
  "description": "OpenCode V2 plugin to warn when a session's context window usage crosses a configurable threshold",
  "exports": {
    ".": "./src/index.ts",
    "./tui": "./src/tui.tsx"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/FAZuH/opencode-context-watch"
  },
  "files": ["src"],
  "license": "MIT",
  "type": "module",
  "keywords": ["opencode", "plugin", "context-window"],
  "scripts": {
    "format": "biome format --write .",
    "lint": "biome check .",
    "typecheck": "tsc --noEmit",
    "bundle": "bun build src/index.ts --outdir dist",
    "test": "bun test",
    "test:typecheck": "tsc -p tsconfig.test.json --noEmit"
  },
  "devDependencies": {
    "@biomejs/biome": "^1.9.0",
    "@types/bun": "^1.3.14",
    "@types/node": "^26.0.0",
    "typescript": "^7.0.0"
  },
  "dependencies": {
    "@opentui/core": "^0.8.3",
    "@opentui/solid": "^0.8.3",
    "solid-js": "^1.9.0"
  }
}
